installer-gui-script.script:
function installationCheck() {
    if (system.compareVersions(system.version.ProductVersion, '14.0') < 0) {
        my.result.title = 'macOS 14 or later required';
        my.result.message = 'MayaFlux requires macOS Sonoma (14.0) or later.';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}

function installationComplete() {
    // Launch Weave.app after installation
    system.run('/usr/bin/open', '/Applications/Weave.app');
    return true;
}
